let marathiWhisperPipeline;
let marathiTextToSpeechPipeline;

async function transcribeMarathiAudio(blob,onProgress) {
  if(!marathiWhisperPipeline){
    marathiWhisperPipeline=(async()=>{
      const {pipeline,env}=await import("@huggingface/transformers");
      env.allowLocalModels=false;
      return pipeline("automatic-speech-recognition","Xenova/whisper-tiny",{progress_callback:event=>{
        if(event.status==="progress"&&event.file?.includes("onnx"))onProgress(`Downloading Marathi speech model · ${Math.round(event.progress||0)}%`);
        else if(event.status==="initiate")onProgress("Preparing Marathi speech model…");
      }});
    })().catch(error=>{marathiWhisperPipeline=null;throw error;});
  }
  const transcriber=await marathiWhisperPipeline;
  const audioUrl=URL.createObjectURL(blob);
  try{return await transcriber(audioUrl,{language:"marathi",task:"transcribe"});}
  finally{URL.revokeObjectURL(audioUrl);}
}

async function synthesizeMarathi(text,onProgress) {
  if(!marathiTextToSpeechPipeline){
    marathiTextToSpeechPipeline=(async()=>{
      const {pipeline,env}=await import("@huggingface/transformers");
      env.allowLocalModels=false;
      return pipeline("text-to-speech","shreyask/bol-tts-marathi-onnx",{dtype:"fp32",progress_callback:event=>{
        if(event.status==="progress"&&event.file?.endsWith(".onnx"))onProgress(`आवाज मॉडेल डाउनलोड होत आहे · ${Math.round(event.progress||0)}%`);
        else if(event.status==="initiate")onProgress("मराठी आवाज मॉडेल तयार होत आहे…");
      }});
    })().catch(error=>{marathiTextToSpeechPipeline=null;throw error;});
  }
  return (await marathiTextToSpeechPipeline)(text);
}

function audioWaveBlob(samples,sampleRate) {
  const buffer=new ArrayBuffer(44+samples.length*2),view=new DataView(buffer);
  const write=(offset,value)=>{for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i));};
  write(0,"RIFF");view.setUint32(4,36+samples.length*2,true);write(8,"WAVE");write(12,"fmt ");view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);write(36,"data");view.setUint32(40,samples.length*2,true);
  for(let i=0;i<samples.length;i++){const sample=Math.max(-1,Math.min(1,samples[i]));view.setInt16(44+i*2,sample<0?sample*0x8000:sample*0x7fff,true);}
  return new Blob([buffer],{type:"audio/wav"});
}

